<script setup lang="ts">
import {MoreHorizontal} from 'lucide-vue-next'
import {DropdownMenuRoot,DropdownMenuTrigger,DropdownMenuPortal,DropdownMenuContent,DropdownMenuItem} from 'reka-ui'
import {useSandboxSession} from '~/composables/useSandboxSession'
const {sandbox,loading,busy,notice,countdown,seconds,start,release,refresh,currentUser}=useSandboxSession()
const labels={creating:'环境创建中',running:'环境运行中',stopping:'环境释放中',cleanup_failed:'等待清理确认'}
</script>
<template><div class="environment-status"><template v-if="currentUser"><span v-if="loading" role="status">获取环境状态…</span><template v-else-if="sandbox.instance"><span>{{sandbox.instance.connected?labels[sandbox.instance.state]:'节点断开'}}</span><time v-if="countdown" :datetime="sandbox.instance.expiresAt||undefined" :class="{soon:seconds!==null && seconds<=120}" title="沙箱剩余时间">{{countdown}}</time></template><button v-else :disabled="busy || !sandbox.available" @click="start">{{busy?'正在启动…':sandbox.available?'启动环境':'环境暂不可用'}}</button><DropdownMenuRoot><DropdownMenuTrigger :disabled="busy" aria-label="环境操作" :title="notice||'环境操作'"><MoreHorizontal :size="17"/></DropdownMenuTrigger><DropdownMenuPortal><DropdownMenuContent class="environment-menu" :side-offset="8"><DropdownMenuItem v-if="sandbox.instance" :disabled="busy" @select="release">释放环境</DropdownMenuItem><DropdownMenuItem @select="refresh">刷新状态</DropdownMenuItem><p v-if="notice" role="alert">{{notice}}</p></DropdownMenuContent></DropdownMenuPortal></DropdownMenuRoot></template><NuxtLink v-else to="/auth">登录后使用环境</NuxtLink></div></template>
<style scoped>.environment-status{display:flex;align-items:center;gap:9px;font-size:11px;color:var(--muted);white-space:nowrap}.environment-status time{font-variant-numeric:tabular-nums}.environment-status .soon{color:var(--error-ink,#d48d72)}.environment-status button{display:inline-flex;align-items:center;justify-content:center;background:transparent;border:0;color:inherit;padding:5px;cursor:pointer}.environment-status button:disabled{opacity:.5}.environment-menu{z-index:130;min-width:160px;max-width:300px;padding:6px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);box-shadow:0 10px 30px #0003;font-size:13px}.environment-menu [role=menuitem]{padding:9px 12px;outline:none;cursor:pointer;border-radius:4px}.environment-menu [data-highlighted]{background:var(--soft)}.environment-menu p{padding:8px 12px;color:var(--error-ink,#c66);white-space:normal}</style>
